import { OrderState } from '../domain/Order';
import { OrderRepository } from '../domain/Repository';
import { UpdateOrderStateResponse } from './DTOs';

export class UpdateOrderStateUseCase {
  constructor(private orderRepository: OrderRepository) {}

  execute(orderId: string, newState: OrderState): UpdateOrderStateResponse {
    const order = this.orderRepository.findById(orderId);
    if (!order) throw new Error(`Order ${orderId} not found`);

    order.transitionTo(newState);
    this.orderRepository.save(order);

    return {
      id: order.id,
      customerId: order.customerId,
      state: order.getState(),
      items: order.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity
      })),
      createdAt: order.createdAt.toISOString()
    };
  }
}

